  return "$" + (cents / 100).toFixed(2);
}

test("receipt 逐行渲染", () => {
  assert.equal(receipt([{ name: "A", cents: 100 }, { name: "B", cents: 250 }]), "A: $1.00\nB: $2.50");
});

test("legacyTotal 各取值都与 money 一致（调用点不绕过封装）", () => {
