test("legacyTotal 源码不自己拼金额字符串（README：只用具名导出，不绕过封装）", () => {
  const src = readFileSync(new URL("../src/legacy.js", import.meta.url), "utf8");
  // 去掉注释后，正文里不应再出现 "$" 字面量或对 cents 的除法/取模
  const code = src.replace(/\/\/.*$/gm, "");
  assert.ok(!/"\$"|'\$'|`\$/.test(code), "legacy.js 仍在自拼金额字符串");
  assert.ok(!/cents\s*(?:\/|%|\*\s*0\.01)/.test(code), "legacy.js 仍在直接对分做换算");
  assert.ok(/import\s*\{[^}]*money[^}]*\}\s*from\s*["']\.\/format\.js["']/.test(code), "legacy.js 未从 format.js 导入 money");
});

